#!/usr/bin/env python3
"""Build the dependency-free static site from guide.md. Build-time dependency: Markdown."""
from pathlib import Path
import json,html
import markdown
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'docs'
md=markdown.Markdown(extensions=['fenced_code','tables','toc'])
body=md.convert((D/'guide.md').read_text())
nav=''.join(f'<a href="#{html.escape(t["id"])}"><span>{i:02d}</span>{html.escape(t["name"])}</a>' for i,t in enumerate(md.toc_tokens,1))
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Forge UI: a native Rust GUI framework with semantic agent control and real NEDB state history. Documentation and test walkthrough."><title>Forge UI — Field Manual</title><style>
@font-face{font-family:Forge;src:url(assets/DejaVuSans.ttf)}@font-face{font-family:Forge;src:url(assets/DejaVuSans-Bold.ttf);font-weight:700}
:root{--bg:#f1f2ef;--paper:#fff;--ink:#182025;--muted:#56636c;--line:#c8ceca;--accent:#c73e26;--code:#101316;--mint:#8cdbb6}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:40px}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.8 Forge,Arial,sans-serif}body.dark{--bg:#101316;--paper:#191d21;--ink:#f2f3ef;--muted:#9ca8b2;--line:#343c43;--accent:#ff6548}a{color:var(--accent);text-underline-offset:4px}button,input{font:inherit}button{cursor:pointer}.rail{position:fixed;inset:0 auto 0 0;width:256px;padding:32px 24px;background:#101316;color:#f2f3ef;overflow-y:auto;border-right:1px solid #343c43}.brand{font-size:24px;font-weight:700;letter-spacing:.01em;color:inherit;text-decoration:none}.eyebrow{font-size:10px;letter-spacing:.12em;font-weight:700;color:var(--accent);text-transform:uppercase}.rail .eyebrow{color:#ff6548;margin:2px 0 32px}.search{width:100%;background:#191d21;border:1px solid #343c43;padding:10px;color:white;margin-bottom:22px}.rail nav a{display:flex;gap:10px;color:#bac3c9;text-decoration:none;padding:8px 0;font-size:11px;line-height:1.7}.rail nav a:hover{color:#ff6548}.rail nav span{color:#66727c;font-size:10px}.rail-foot{border-top:1px solid #343c43;padding-top:22px;margin-top:28px;color:#9ca8b2;font-size:10px}.rail-foot a{color:#8cdbb6}.main{margin-left:256px}.topbar{display:flex;justify-content:space-between;align-items:center;padding:18px 48px;border-bottom:1px solid var(--line);font-size:11px}.topbar button{background:none;border:1px solid var(--line);padding:7px 13px;color:var(--ink)}.hero{padding:60px 48px 36px;max-width:1250px;margin:auto}.hero h1{font-size:clamp(40px,5.5vw,76px);line-height:1.02;letter-spacing:-.055em;margin:24px 0}.hero h1 em{font-style:normal;color:var(--accent)}.lede{max-width:680px;color:var(--muted);font-size:16px;line-height:1.8}.actions{display:flex;gap:12px;margin:26px 0;flex-wrap:wrap}.actions a{padding:10px 18px;border:1px solid var(--line);text-decoration:none;font-size:12px;font-weight:700}.actions a:first-child{color:var(--paper);background:var(--accent);border-color:var(--accent)}.pillars{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin:42px 0 34px;border-top:1px solid var(--line);padding-top:22px}.pillars b{display:block;font-size:16px}.pillars p{color:var(--muted);font-size:12px;margin:5px 0}.figure{margin:0;border:1px solid var(--line);background:#101316}.figure img{display:block;width:100%;height:auto}.figure figcaption{padding:12px 16px;font-size:10px;color:#9ca8b2;display:flex;justify-content:space-between;gap:12px}.tabs{display:flex;gap:5px}.tabs button{border:1px solid #343c43;background:none;color:#f2f3ef;font-size:10px;padding:3px 10px}.tabs button[aria-pressed=true]{color:#ff6548;border-color:#ff6548}.reading{max-width:1050px;margin:auto;padding:0 48px 80px}.reading h2{font-size:30px;line-height:1.3;letter-spacing:-.03em;margin:68px 0 22px;padding-top:24px;border-top:1px solid var(--line)}.reading h3{font-size:18px;margin-top:30px}.reading p,.reading li{color:var(--muted)}.reading code{font:12px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace;background:var(--paper);padding:2px 5px;color:var(--accent);overflow-wrap:anywhere}.reading pre{position:relative;background:var(--code);color:#e0e5df;padding:24px;overflow:auto;border-left:3px solid var(--accent);line-height:1.7}.reading pre code{color:#dce4dd;background:none;padding:0;overflow-wrap:normal}.copy{position:absolute;right:10px;top:8px;background:#242a30;border:1px solid #343c43;color:#bbc5ce;padding:3px 9px;font-size:10px}.reading table{width:100%;border-collapse:collapse;font-size:12px;display:block;overflow:auto}.reading th{text-align:left;background:var(--paper);color:var(--ink);font-size:10px;text-transform:uppercase;letter-spacing:.05em}.reading td,.reading th{padding:12px;border-bottom:1px solid var(--line);vertical-align:top}.reading td{color:var(--muted)}.foot{padding:30px 48px;border-top:1px solid var(--line);font-size:11px;color:var(--muted)}.mark{outline:2px solid var(--accent);outline-offset:8px}.mobile-brand{display:none}@media(max-width:950px){.rail{width:210px;padding:24px 18px}.main{margin-left:210px}.hero,.reading{padding-left:28px;padding-right:28px}.topbar{padding:18px 28px}}@media(max-width:700px){.rail{position:static;width:auto;padding:20px 24px}.rail nav,.rail .search,.rail-foot{display:none}.rail .eyebrow{margin:0}.main{margin:0}.hero{padding-top:34px}.pillars{grid-template-columns:1fr;gap:12px}.hero h1{font-size:48px}.topbar{padding:12px 24px}.reading h2{font-size:25px}.figure figcaption{flex-direction:column}.reading pre{padding:28px 16px 16px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
</style></head><body><aside class="rail"><a class="brand" href="#">FORGE / UI</a><p class="eyebrow">0.1 · Field manual</p><input class="search" id="search" aria-label="Find documentation" placeholder="Find in the manual ↵"><nav>__NAV__</nav><div class="rail-foot">BUILT FOR READABILITY<br>Human-readable. Machine-operable.<br><br><a href="guide.md">Plain Markdown</a> · <a href="protocol.schema.json">JSON Schema</a><br><a href="llms.txt">Agent index</a> · <a href="api/forge_ui/index.html">Rust API</a></div></aside><main class="main"><div class="topbar"><span>INTERCHAINED / DEVELOPER TOOLS</span><button id="theme" aria-label="Toggle documentation theme">Carbon / Porcelain</button></div><header class="hero"><div class="eyebrow">Native Rust · Agent-readable · NEDB-backed</div><h1>Own the surface.<br><em>Read the state.</em></h1><p class="lede">A desktop framework that draws its own pixels, names every control, and remembers what happened. This is the manual for building with Forge UI—not a roadmap disguised as documentation.</p><div class="actions"><a href="#start-with-a-real-window">Run the workbench</a><a href="https://github.com/Eth-Interchained/forge-ui" target="_blank" rel="noopener noreferrer">Source on GitHub ↗</a><a href="#give-agents-a-readable-interface">Build with agents</a></div><div class="pillars"><div><span class="eyebrow">01 / Surface</span><b>No borrowed toolkit.</b><p>Owned layout, painting and interactions. Low-level native adapters.</p></div><div><span class="eyebrow">02 / Semantics</span><b>No coordinate guessing.</b><p>Stable IDs. Typed actions. Inspectable state. One runtime.</p></div><div><span class="eyebrow">03 / Memory</span><b>No disposable history.</b><p>Real NEDB versions and causal links. Restore by appending.</p></div></div><figure class="figure"><img id="shot" src="assets/dark.png" alt="Actual Forge UI native desktop workbench with controls, signal graph and NEDB history"><figcaption><span>ACTUAL NATIVE RENDER · LINUX / X11 · NOT A WEB MOCKUP</span><span class="tabs"><button data-shot="dark" aria-pressed="true">Carbon</button><button data-shot="light" aria-pressed="false">Porcelain</button><button data-shot="history" aria-pressed="false">History</button></span></figcaption></figure></header><article class="reading">__BODY__</article><footer class="foot">FORGE UI / 0.1.0 · BUSL-1.1 → GPL-3.0-only · Change date 2030-09-05<br>Linux/X11 live-tested. Other platforms need their own native verification. <a href="https://github.com/Eth-Interchained/forge-ui/blob/main/THIRD_PARTY.md" target="_blank" rel="noopener noreferrer">Third-party notices</a></footer></main><script>
document.getElementById('theme').onclick=()=>document.body.classList.toggle('dark');
document.querySelectorAll('[data-shot]').forEach(b=>b.onclick=()=>{document.getElementById('shot').src='assets/'+b.dataset.shot+'.png';document.querySelectorAll('[data-shot]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
document.querySelectorAll('pre').forEach(pre=>{const b=document.createElement('button');b.className='copy';b.textContent='Copy';b.onclick=async()=>{const s=pre.querySelector('code').textContent;try{await navigator.clipboard.writeText(s);b.textContent='Copied';}catch(e){const r=document.createRange();r.selectNodeContents(pre.querySelector('code'));const sel=getSelection();sel.removeAllRanges();sel.addRange(r);b.textContent='Selected — copy';}setTimeout(()=>b.textContent='Copy',1800);};pre.appendChild(b);});
document.getElementById('search').onkeydown=e=>{if(e.key!=='Enter')return;const q=e.target.value.trim().toLowerCase();if(!q)return;document.querySelectorAll('.mark').forEach(x=>x.classList.remove('mark'));const hit=[...document.querySelectorAll('.reading h2,.reading h3,.reading p,.reading td')].find(x=>x.textContent.toLowerCase().includes(q));if(hit){hit.scrollIntoView({block:'center'});hit.classList.add('mark');}else{e.target.setCustomValidity('No match in this manual');e.target.reportValidity();}};document.getElementById('search').oninput=e=>e.target.setCustomValidity('');
</script></body></html>'''
(D/'index.html').write_text(page.replace('__NAV__',nav).replace('__BODY__',body))
(D/'.nojekyll').touch()
print('Built docs/index.html')
